import Darwin
import Foundation

/// A local TCP listener. The browser uses HTTP unless the terminal advertises HTTPS for this port.
public struct LocalServer: Hashable, Sendable {
  private static let urlExpression = try! NSRegularExpression(
    pattern: #"https?://[^\s<>\"']+"#, options: .caseInsensitive)
  public let host: String
  public let port: UInt16

  public init(host: String, port: UInt16) {
    self.host = host
    self.port = port
  }

  public var address: String { "\(host.contains(":") ? "[\(host)]" : host):\(port)" }

  public func browserURL(screenText: String = "", preferringHTTPS: Bool = false) -> URL {
    var scheme = preferringHTTPS ? "https" : "http"
    // Only use the scheme, never a terminal-provided destination or executable URL scheme.
    do {
      let text = String(screenText.suffix(32_768))
      for match in Self.urlExpression.matches(
        in: text, range: NSRange(text.startIndex..., in: text))
      {
        guard let range = Range(match.range, in: text),
          let parts = URLComponents(string: String(text[range])),
          ["localhost", "127.0.0.1", "0.0.0.0", "[::1]", "[::]", host].contains(
            parts.host?.lowercased() ?? ""),
          parts.user == nil, parts.password == nil,
          (parts.port ?? (parts.scheme?.lowercased() == "https" ? 443 : 80)) == Int(port)
        else { continue }
        scheme = parts.scheme?.lowercased() == "https" ? "https" : "http"
      }
    }
    return URL(string: "\(scheme)://\(address)")!
  }
}

/// Inspect only the supplied shells and their descendants. No shell command, system-wide port scan,
/// environment read, or network request is needed.
public enum LocalServerDiscovery {
  public static func scan(rootPIDs: [Int32]) -> [Int32: [LocalServer]] {
    var result: [Int32: [LocalServer]] = [:]
    let ownedRoots = Set(children(of: getpid()))
    for root in Set(rootPIDs) where root > 0 {
      guard !Task.isCancelled, root == getpid() || ownedRoots.contains(root)
      else { continue }
      let before = identity(root)
      var pending = [root]
      var visited = Set<Int32>()
      var servers = Set<LocalServer>()
      while let pid = pending.popLast(), visited.count < 4096, !Task.isCancelled {
        let process = identity(pid)
        guard pid == root || process.map({ visited.contains(Int32($0.pbi_ppid)) }) == true,
          visited.insert(pid).inserted
        else { continue }
        if let process {
          // Agent transports listen on loopback too. Their own sockets are not app previews;
          // keep traversing their children so an agent-started dev server is still discovered.
          let found = isPreviewProcess(pid) ? listeners(pid) : []
          if let current = identity(pid), process.pbi_start_tvsec == current.pbi_start_tvsec,
            process.pbi_start_tvusec == current.pbi_start_tvusec,
            process.pbi_ppid == current.pbi_ppid
          {
            servers.formUnion(found)
          }
        }
        // macOS login(1) is privileged: its BSD info can be denied even though its children are ours.
        pending += children(of: pid)
      }
      if let before {
        guard let after = identity(root), before.pbi_start_tvsec == after.pbi_start_tvsec,
          before.pbi_start_tvusec == after.pbi_start_tvusec, before.pbi_ppid == after.pbi_ppid
        else { continue }
      } else if !children(of: getpid()).contains(root) {
        continue
      }
      result[root] = servers.sorted {
        $0.port == $1.port ? $0.host < $1.host : $0.port < $1.port
      }
    }
    return result
  }

  private static func children(of pid: Int32) -> [Int32] {
    // Unlike proc_pidinfo, proc_listchildpids returns a PID count, not a byte count.
    let capacity = Int(proc_listchildpids(pid, nil, 0)) + 32
    guard capacity > 0, capacity < 65_536 else { return [] }
    var children = [Int32](repeating: 0, count: capacity)
    let count = children.withUnsafeMutableBytes {
      proc_listchildpids(pid, $0.baseAddress, Int32($0.count))
    }
    return count > 0 ? children.prefix(Int(count)).filter { $0 > 0 } : []
  }

  private static func identity(_ pid: Int32) -> proc_bsdinfo? {
    var info = proc_bsdinfo()
    let size = Int32(MemoryLayout.size(ofValue: info))
    return proc_pidinfo(pid, PROC_PIDTBSDINFO, 0, &info, size) == size ? info : nil
  }

  private static func isPreviewProcess(_ pid: Int32) -> Bool {
    // PROC_PIDPATHINFO_MAXSIZE is a C expression macro, unavailable to Swift.
    var buffer = [CChar](repeating: 0, count: 4 * Int(MAXPATHLEN))
    let count = proc_pidpath(pid, &buffer, UInt32(buffer.count))
    guard count > 0 else { return true }
    let path = String(
      decoding: buffer.prefix { $0 != 0 }.map { UInt8(bitPattern: $0) }, as: UTF8.self)
    return URL(fileURLWithPath: path).lastPathComponent != "codex"
  }

  private static func listeners(_ pid: Int32) -> [LocalServer] {
    let stride = MemoryLayout<proc_fdinfo>.stride
    let required = Int(proc_pidinfo(pid, PROC_PIDLISTFDS, 0, nil, 0))
    guard required > 0, required < 16_777_216 else { return [] }
    var descriptors = [proc_fdinfo](repeating: proc_fdinfo(), count: required / stride + 32)
    let bytes = descriptors.withUnsafeMutableBytes {
      proc_pidinfo(pid, PROC_PIDLISTFDS, 0, $0.baseAddress, Int32($0.count))
    }
    guard bytes > 0 else { return [] }
    var result: [LocalServer] = []
    for descriptor in descriptors.prefix(Int(bytes) / stride)
    where descriptor.proc_fdtype == UInt32(PROX_FDTYPE_SOCKET) {
      if Task.isCancelled { break }
      var socket = socket_fdinfo()
      let size = Int32(MemoryLayout.size(ofValue: socket))
      guard proc_pidfdinfo(pid, descriptor.proc_fd, PROC_PIDFDSOCKETINFO, &socket, size) == size,
        socket.psi.soi_kind == SOCKINFO_TCP,
        socket.psi.soi_proto.pri_tcp.tcpsi_state == TSI_S_LISTEN
      else { continue }
      let info = socket.psi.soi_proto.pri_tcp.tcpsi_ini
      let port = UInt16(bigEndian: UInt16(truncatingIfNeeded: info.insi_lport))
      guard port > 0 else { continue }
      if info.insi_vflag & UInt8(INI_IPV4) != 0 {
        var address = info.insi_laddr.ina_46.i46a_addr4
        let value = UInt32(bigEndian: address.s_addr)
        guard value == 0 || value >> 24 == 127 else { continue }
        var buffer = [CChar](repeating: 0, count: Int(INET_ADDRSTRLEN))
        guard inet_ntop(AF_INET, &address, &buffer, socklen_t(buffer.count)) != nil else {
          continue
        }
        let host =
          value == 0 || value == 0x7f00_0001
          ? "localhost"
          : String(decoding: buffer.prefix { $0 != 0 }.map { UInt8(bitPattern: $0) }, as: UTF8.self)
        result.append(LocalServer(host: host, port: port))
      } else if info.insi_vflag & UInt8(INI_IPV6) != 0 {
        var address = info.insi_laddr.ina_6
        let values = withUnsafeBytes(of: &address) { Array($0) }
        guard
          values.allSatisfy({ $0 == 0 })
            || (values.dropLast().allSatisfy({ $0 == 0 }) && values.last == 1)
        else { continue }
        result.append(LocalServer(host: "localhost", port: port))
      }
    }
    return result
  }
}

import Darwin
import Foundation
import Testing

@testable import ChopCore

@MainActor
@Test func agentTransportIsExcludedWithoutHidingItsDevServer() async throws {
  let directory = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
  try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: false)
  defer { try? FileManager.default.removeItem(at: directory) }
  // A real executable named codex owns an internal listener and launches a separate server.
  // This catches filtering the whole agent subtree instead of just its transport sockets.
  let source = """
    #include <arpa/inet.h>
    #include <signal.h>
    #include <stdio.h>
    #include <sys/wait.h>
    #include <unistd.h>
    int main(int argc, char **argv) {
      int fd = socket(AF_INET, SOCK_STREAM, 0);
      struct sockaddr_in addr = {.sin_family=AF_INET, .sin_addr.s_addr=htonl(INADDR_LOOPBACK)};
      if (bind(fd, (struct sockaddr *)&addr, sizeof(addr)) || listen(fd, 4)) return 1;
      socklen_t len = sizeof(addr);
      if (getsockname(fd, (struct sockaddr *)&addr, &len)) return 2;
      FILE *out = fopen(argv[1], "w");
      if (!out) return 3;
      fprintf(out, "%u", ntohs(addr.sin_port)); fclose(out);
      pid_t child = fork();
      if (child < 0) return 4;
      if (!child) {
        close(fd);
        execl("/usr/bin/python3", "python3", "-c",
          "import socket,sys,time; s=socket.socket(); s.bind(('127.0.0.1',0)); s.listen(); open(sys.argv[1],'w').write(str(s.getsockname()[1])); time.sleep(30)",
          argv[2], NULL);
        _exit(5);
      }
      char command;
      read(STDIN_FILENO, &command, 1);
      kill(child, SIGKILL); waitpid(child, NULL, 0); close(fd);
      return 0;
    }
    """
  let sourceURL = directory.appendingPathComponent("fixture.c")
  let executable = directory.appendingPathComponent("codex")
  try source.write(to: sourceURL, atomically: true, encoding: .utf8)
  let compiler = Process()
  compiler.executableURL = URL(fileURLWithPath: "/usr/bin/clang")
  compiler.arguments = [sourceURL.path, "-o", executable.path]
  try compiler.run()
  defer { if compiler.isRunning { kill(compiler.processIdentifier, SIGKILL) } }
  let compileDeadline = ContinuousClock.now.advanced(by: .seconds(15))
  while compiler.isRunning, ContinuousClock.now < compileDeadline {
    try await Task.sleep(for: .milliseconds(20))
  }
  try #require(!compiler.isRunning)
  try #require(compiler.terminationStatus == 0)
  let agentPortFile = directory.appendingPathComponent("agent-port")
  let serverPortFile = directory.appendingPathComponent("server-port")
  let input = Pipe()
  let agent = Process()
  agent.executableURL = executable
  agent.arguments = [agentPortFile.path, serverPortFile.path]
  agent.standardInput = input
  try agent.run()
  defer { try? input.fileHandleForWriting.close() }
  let deadline = ContinuousClock.now.advanced(by: .seconds(5))
  var serverPort: UInt16?
  while serverPort == nil, ContinuousClock.now < deadline {
    serverPort = (try? String(contentsOf: serverPortFile, encoding: .utf8)).flatMap(UInt16.init)
    if serverPort == nil { try await Task.sleep(for: .milliseconds(20)) }
  }
  let port = try #require(serverPort)
  let internalPort = try #require(
    (try? String(contentsOf: agentPortFile, encoding: .utf8)).flatMap(UInt16.init))
  let servers = LocalServerDiscovery.scan(rootPIDs: [agent.processIdentifier])
  #expect(
    servers[agent.processIdentifier]?.contains(LocalServer(host: "localhost", port: port)) == true)
  #expect(
    servers[agent.processIdentifier]?.contains(LocalServer(host: "localhost", port: internalPort))
      == false)
  try input.fileHandleForWriting.close()
  let exitDeadline = ContinuousClock.now.advanced(by: .seconds(5))
  while agent.isRunning, ContinuousClock.now < exitDeadline {
    try await Task.sleep(for: .milliseconds(20))
  }
  #expect(!agent.isRunning)
}

@MainActor
@Test func localServerDiscoveryReadsAChildProcessWithoutIncludingOtherRoots() async throws {
  let marker = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
  let process = Process()
  process.executableURL = URL(fileURLWithPath: "/usr/bin/python3")
  process.arguments = [
    "-c",
    "import socket,time,sys; s=socket.socket(); s.bind(('127.0.0.1',0)); s.listen(); open(sys.argv[1],'w').write(str(s.getsockname()[1])); time.sleep(30)",
    marker.path,
  ]
  try process.run()
  defer {
    if process.isRunning {
      kill(process.processIdentifier, SIGKILL)
    }
    try? FileManager.default.removeItem(at: marker)
  }
  let deadline = ContinuousClock.now.advanced(by: .seconds(5))
  var announcedPort: UInt16?
  while announcedPort == nil, ContinuousClock.now < deadline {
    announcedPort = (try? String(contentsOf: marker, encoding: .utf8)).flatMap(UInt16.init)
    if announcedPort != nil { break }
    try await Task.sleep(for: .milliseconds(20))
  }
  let port = try #require(announcedPort)
  let root = process.processIdentifier
  let found = LocalServerDiscovery.scan(rootPIDs: [root])
  #expect(found[root]?.contains(LocalServer(host: "localhost", port: port)) == true)
  #expect(LocalServerDiscovery.scan(rootPIDs: [getppid()]).isEmpty)
  process.terminate()
  // Foundation Process keeps run-loop state. Never block a test indefinitely in waitUntilExit.
  let exitDeadline = ContinuousClock.now.advanced(by: .seconds(5))
  while process.isRunning, ContinuousClock.now < exitDeadline {
    try await Task.sleep(for: .milliseconds(20))
  }
  #expect(!process.isRunning, "검사 서버가 제한 시간 안에 종료되어야 합니다.")
}

@Test func localServerHintsCannotReplaceTheListenerDestination() {
  let server = LocalServer(host: "localhost", port: 3000)
  #expect(server.browserURL().absoluteString == "http://localhost:3000")
  #expect(server.browserURL(preferringHTTPS: true).scheme == "https")
  #expect(server.browserURL(screenText: "HTTPS://LOCALHOST:3000").scheme == "https")
  #expect(
    server.browserURL(screenText: "http://localhost:3000", preferringHTTPS: true).scheme == "http")
  #expect(
    server.browserURL(screenText: "Local: https://localhost:3000/base/").absoluteString
      == "https://localhost:3000")
  for text in [
    "https://localhost.evil.example:3000", "https://user@localhost:3000", "https://localhost:4000",
    "file:///tmp/localhost:3000", "https://example.com:3000",
  ] {
    #expect(server.browserURL(screenText: text).absoluteString == "http://localhost:3000")
  }
  #expect(LocalServer(host: "127.0.0.2", port: 8080).browserURL().host == "127.0.0.2")
}

@Test func localServerDiscoveryTracksActualListenersAndRemovesClosedPorts() throws {
  let descriptor = socket(AF_INET, SOCK_STREAM, 0)
  #expect(descriptor >= 0)
  guard descriptor >= 0 else { return }
  var shouldClose = true
  defer { if shouldClose { close(descriptor) } }
  var address = sockaddr_in()
  address.sin_len = UInt8(MemoryLayout<sockaddr_in>.size)
  address.sin_family = sa_family_t(AF_INET)
  address.sin_addr.s_addr = inet_addr("127.0.0.1")
  let bound = withUnsafePointer(to: &address) {
    $0.withMemoryRebound(to: sockaddr.self, capacity: 1) {
      bind(descriptor, $0, socklen_t(MemoryLayout<sockaddr_in>.size))
    }
  }
  #expect(bound == 0)
  var size = socklen_t(MemoryLayout<sockaddr_in>.size)
  let named = withUnsafeMutablePointer(to: &address) {
    $0.withMemoryRebound(to: sockaddr.self, capacity: 1) { getsockname(descriptor, $0, &size) }
  }
  #expect(named == 0)
  let port = UInt16(bigEndian: address.sin_port)
  let expected = LocalServer(host: "localhost", port: port)
  // A bound TCP socket that has not begun listening must not be advertised.
  #expect(LocalServerDiscovery.scan(rootPIDs: [getpid()])[getpid()]?.contains(expected) == false)
  #expect(listen(descriptor, 4) == 0)
  #expect(LocalServerDiscovery.scan(rootPIDs: [getpid()])[getpid()]?.contains(expected) == true)
  #expect(LocalServerDiscovery.scan(rootPIDs: [-1, 0]).isEmpty)
  close(descriptor)
  shouldClose = false
  #expect(LocalServerDiscovery.scan(rootPIDs: [getpid()])[getpid()]?.contains(expected) == false)
}
